mapper.select:
SELECT

FROM site_user_oauth_accounts oa
JOIN site_users su ON su.id = oa.user_id
WHERE oa.oauth_provider = #{provider}
  AND oa.oauth_provider_id = #{providerId}
LIMIT 1

mapper.update:
UPDATE site_users
SET last_login_at = NOW()
WHERE id = #{id}

mapper.select:
SELECT id, public_id AS publicId, service_nickname AS nickname, email AS email, user_role AS userRole, user_status AS userStatus, last_login_at AS lastLoginAt, created_at AS createdAt FROM site_users
service_nickname LIKE CONCAT('%', #{nickname}, '%')
AND user_role = #{userRole}
AND user_status = #{userStatus}
ORDER BY created_at DESC LIMIT #{limit} OFFSET #{offset}
